import os, json, urllib.request
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
url=os.environ['GALAXY_URL']+'/api/tools/toolshed.g2.bx.psu.edu%2Frepos%2Fdevteam%2Fbwa%2Fbwa_mem%2F0.7.19%2Bgalaxy1?io_details=true'
req=urllib.request.Request(url, headers={'x-api-key':key})
data=json.load(urllib.request.urlopen(req))
for inp in data['inputs']:
    if inp.get('name')=='reference_source':
        for case in inp['cases']:
            if case['value']=='cached':
                for p in case['inputs']:
                    if p['name']=='ref_file':
                        for opt in p['options']:
                            if any(s in opt[0].lower() or s in opt[1].lower() for s in ['human','hg19','hg38','grch']):
                                print(opt)
PY"

