import os,json,urllib.request,urllib.parse
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
tid='toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1'
url=os.environ['GALAXY_URL']+'/api/tools/'+urllib.parse.quote(tid,safe='')+'?io_details=true'
req=urllib.request.Request(url,headers={'x-api-key':key})
data=json.load(urllib.request.urlopen(req))
for inp in data['inputs']:
    print('TOP', inp['name'], inp['type'])
    if inp['name']=='fastq_input':
      for c in inp['cases']:
       print('case',c['value'])
       for p in c['inputs']:
        print(' field',p['name'],p['type'])
        if p['name'] in ('fastq_input1','fastq_input2'):
         print(json.dumps(p,indent=2)[:1000])
    if inp['name']=='reference_source':
      for c in inp['cases']:
       if c['value']=='cached':
        for p in c['inputs']:
         if p['name']=='ref_file': print('ref model',json.dumps(p,indent=2)[:500])
PY"

